package edu.sharespace;

import edu.sharespace.Domain.*;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.web.server.ResponseStatusException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;

class WorkflowTest {
 UserRepository users=mock(UserRepository.class);ResourceRepository resources=mock(ResourceRepository.class);BookingRepository bookings=mock(BookingRepository.class);ConditionRepository conditions=mock(ConditionRepository.class);IncidentRepository incidents=mock(IncidentRepository.class);AuditRepository audit=mock(AuditRepository.class);Workflow workflow;
 User student=new User("Taylor Morgan","taylor@campus.edu",Role.USER),owner=new User("Maya Chen","maya@campus.edu",Role.OWNER);Resource camera=new Resource();
 @BeforeEach void setup(){student.id=10L;owner.id=20L;camera.id=30L;camera.name="Camera";camera.owner=owner;camera.maxBookingHours=8;camera.requiresApproval=true;camera.status="AVAILABLE";workflow=new Workflow(users,resources,bookings,conditions,incidents,audit);ReflectionTestUtils.setField(workflow,"activeBookingLimit",3);ReflectionTestUtils.setField(workflow,"waitlistEnabled",true);when(users.findByIdForUpdate(10L)).thenReturn(Optional.of(student));when(resources.findByIdForUpdate(30L)).thenReturn(Optional.of(camera));when(bookings.save(any())).thenAnswer(a->{Booking b=a.getArgument(0);if(b.id==null)b.id=100L;return b;});when(audit.save(any())).thenAnswer(a->a.getArgument(0));when(incidents.save(any())).thenAnswer(a->{Incident i=a.getArgument(0);i.id=200L;return i;});when(bookings.findByRequesterIdOrderByCreatedAtDesc(10L)).thenReturn(new ArrayList<>());when(bookings.findByResourceIdAndStatusInAndStartTimeLessThanAndEndTimeGreaterThan(anyLong(),anyList(),any(),any())).thenReturn(new ArrayList<>());}
 BookingIn request(){OffsetDateTime start=OffsetDateTime.now().plusDays(2);return new BookingIn(30L,start,start.plusHours(2),"Course project");}
 @Test void authenticatedUserCanCreateResourceWithServerAssignedOwnership() throws Exception {ResourceIn in=new ResourceIn("Campus camera","Camera kit for student projects","Photography","Media Lab",false,null,true,8,"Handle carefully",null);when(resources.save(any(Resource.class))).thenAnswer(a->{Resource r=a.getArgument(0);r.id=31L;return r;});Resource created=workflow.create(in,student);assertSame(student,created.owner);verify(resources).save(argThat(r->r.owner.id.equals(student.id)));verify(audit).save(argThat(e->e.action.equals("RESOURCE_CREATED")&&e.entityId.equals(31L)));String json=new ObjectMapper().findAndRegisterModules().writeValueAsString(ResourceView.from(created));assertFalse(json.contains("email"));assertFalse(json.contains("firebaseUid"));assertFalse(json.contains("role"));}
 @Test void differentUserCannotEditAnotherUsersResource(){when(resources.findById(30L)).thenReturn(Optional.of(camera));ResourceIn in=new ResourceIn("Changed camera","Updated description","Photography","Media Lab",false,null,true,8,"Handle carefully",null);ResponseStatusException error=assertThrows(ResponseStatusException.class,()->workflow.update(30L,in,student));assertEquals(403,error.getStatusCode().value());verify(resources,never()).save(any());}
 @Test void resourceOwnerUserCanDecideOnlyTheirOwnBooking(){camera.owner=student;Booking b=makeBooking(BookingStatus.PENDING);when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));Booking result=workflow.decide(100L,student,true,"Approved for use");assertEquals(BookingStatus.APPROVED,result.status);verify(audit).save(argThat(e->e.action.equals("BOOKING_APPROVED")));}
 @Test void anotherUserCannotDecideBookingForResource(){camera.owner=student;Booking b=makeBooking(BookingStatus.PENDING);User stranger=new User("Stranger","stranger@example.edu",Role.USER);stranger.id=99L;when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));ResponseStatusException error=assertThrows(ResponseStatusException.class,()->workflow.decide(100L,stranger,true,"Not authorized"));assertEquals(403,error.getStatusCode().value());verify(bookings,never()).save(any());}
 @Test void userSeesBookingsTheyRequestedOrForResourcesTheyOwnOnly(){camera.owner=student;Booking ownedResourceRequest=makeBooking(BookingStatus.PENDING);ownedResourceRequest.requester=owner;ownedResourceRequest.id=101L;Resource otherResource=new Resource();otherResource.id=31L;otherResource.owner=owner;Booking ownRequest=makeBooking(BookingStatus.PENDING);ownRequest.id=102L;ownRequest.resource=otherResource;Booking unrelated=makeBooking(BookingStatus.PENDING);unrelated.id=103L;unrelated.requester=owner;unrelated.resource=otherResource;when(bookings.findAllByOrderByCreatedAtDesc()).thenReturn(List.of(ownedResourceRequest,ownRequest,unrelated));assertEquals(Set.of(101L,102L),workflow.visibleBookings(student).stream().map(b->b.id).collect(java.util.stream.Collectors.toSet()));}
 @Test void resourceOwnerUserCanResolveIncidentForTheirResource(){camera.owner=student;Booking b=makeBooking(BookingStatus.COMPLETED);Incident i=new Incident();i.id=200L;i.booking=b;i.status=IncidentStatus.OPEN;when(incidents.findByIdForUpdate(200L)).thenReturn(Optional.of(i));Incident resolved=workflow.resolve(200L,new ResolveIn("Checked and recorded"),student);assertEquals(IncidentStatus.RESOLVED,resolved.status);verify(audit).save(argThat(e->e.action.equals("INCIDENT_RESOLVED")));}
 @Test void anotherUserCannotResolveIncidentForResource(){Booking b=makeBooking(BookingStatus.COMPLETED);Incident i=new Incident();i.id=200L;i.booking=b;i.status=IncidentStatus.OPEN;User stranger=new User("Stranger","stranger@example.edu",Role.USER);stranger.id=99L;when(incidents.findByIdForUpdate(200L)).thenReturn(Optional.of(i));ResponseStatusException error=assertThrows(ResponseStatusException.class,()->workflow.resolve(200L,new ResolveIn("Not authorized"),stranger));assertEquals(403,error.getStatusCode().value());verify(incidents,never()).save(any());}
 @Test void rejectsEndNotAfterStart(){BookingIn in=new BookingIn(30L,OffsetDateTime.now().plusDays(1),OffsetDateTime.now().plusHours(1),"test");when(resources.findByIdForUpdate(30L)).thenReturn(Optional.of(camera));assertThrows(ResponseStatusException.class,()->workflow.request(in,student));}
 @Test void rejectsDurationOverResourceLimit(){OffsetDateTime start=OffsetDateTime.now().plusDays(1);BookingIn in=new BookingIn(30L,start,start.plusHours(8).plusMinutes(1),"test");assertThrows(ResponseStatusException.class,()->workflow.request(in,student));}
 @Test void createsPendingRequestAndAuditEvent(){when(resources.findByIdForUpdate(30L)).thenReturn(Optional.of(camera));Booking b=workflow.request(request(),student);assertEquals(BookingStatus.PENDING,b.status);verify(audit).save(argThat(e->e.action.equals("BOOKING_REQUESTED")&&e.actor==student));}
 @Test void eligibleRequestIsInstantlyApprovedWhenResourceAllowsIt(){camera.requiresApproval=false;Booking b=workflow.request(request(),student);assertEquals(BookingStatus.APPROVED,b.status);assertTrue(b.decisionReason.contains("Automatically approved"));verify(audit).save(argThat(e->e.action.equals("BOOKING_AUTO_APPROVED")));}
 @Test void enforcesConfigurableActiveBookingLimit(){List<Booking> current=new ArrayList<>();for(BookingStatus status:List.of(BookingStatus.PENDING,BookingStatus.APPROVED,BookingStatus.CHECKED_OUT)){Booking b=new Booking();b.status=status;current.add(b);}when(bookings.findByRequesterIdOrderByCreatedAtDesc(10L)).thenReturn(current);assertThrows(ResponseStatusException.class,()->workflow.request(request(),student));}
 @Test void conflictingReservationIsWaitlisted(){OffsetDateTime start=request().startTime();Booking occupied=new Booking();occupied.id=90L;when(bookings.findByResourceIdAndStatusInAndStartTimeLessThanAndEndTimeGreaterThan(anyLong(),anyList(),any(),any())).thenReturn(List.of(occupied));Booking b=workflow.request(request(),student);assertEquals(BookingStatus.WAITLISTED,b.status);assertTrue(b.decisionReason.contains("FIFO"));verify(audit).save(argThat(e->e.action.equals("BOOKING_WAITLISTED")));}
 @Test void refusesApprovalForUnverifiedRequiredTraining(){camera.requiresTraining=true;camera.requiredTrainingDescription="Safety";student.training="Safety";student.verified=false;Booking b=makeBooking(BookingStatus.PENDING);when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));Booking result=workflow.decide(100L,owner,true,"Looks good");assertEquals(BookingStatus.REJECTED,result.status);assertTrue(result.decisionReason.contains("Verified training"));}
 @Test void refusesApprovalWhenAnotherBookingNowConflicts(){Booking b=makeBooking(BookingStatus.PENDING);when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));when(bookings.findByResourceIdAndStatusInAndStartTimeLessThanAndEndTimeGreaterThan(anyLong(),anyList(),any(),any())).thenReturn(List.of(new Booking()));assertThrows(ResponseStatusException.class,()->workflow.decide(100L,owner,true,"Approved"));}
 @Test void approvalAndRejectionRecordDecisionReason(){Booking b=makeBooking(BookingStatus.PENDING);when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));Booking approved=workflow.decide(100L,owner,true,"Approved for class project");assertEquals(BookingStatus.APPROVED,approved.status);assertEquals("Approved for class project",approved.decisionReason);verify(audit).save(argThat(e->e.action.equals("BOOKING_APPROVED")&&e.reason.equals("Approved for class project")));}
 @Test void rejectionRecordsOwnerReason(){Booking b=makeBooking(BookingStatus.PENDING);when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));Booking rejected=workflow.decide(100L,owner,false,"Resource is reserved for a lab course");assertEquals(BookingStatus.REJECTED,rejected.status);assertEquals("Resource is reserved for a lab course",rejected.decisionReason);verify(audit).save(argThat(e->e.action.equals("BOOKING_REJECTED")&&e.reason.equals("Resource is reserved for a lab course")));}
 @Test void rejectsCheckInBeforeApproval(){Booking b=makeBooking(BookingStatus.PENDING);when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));assertThrows(ResponseStatusException.class,()->workflow.transition(100L,student,"check-in"));}
 @Test void requiresBeforeReportForCheckIn(){Booking b=makeBooking(BookingStatus.APPROVED);when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));when(conditions.existsByBookingIdAndReportType(100L,ReportType.BEFORE)).thenReturn(false);assertThrows(ResponseStatusException.class,()->workflow.transition(100L,student,"check-in"));}
 @Test void requiresAfterReportBeforeReturn(){Booking b=makeBooking(BookingStatus.CHECKED_OUT);when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));when(conditions.existsByBookingIdAndReportType(100L,ReportType.AFTER)).thenReturn(false);assertThrows(ResponseStatusException.class,()->workflow.transition(100L,student,"return"));}
 @Test void requiresOwnerConfirmationAfterReturn(){Booking b=makeBooking(BookingStatus.RETURN_PENDING_CONFIRMATION);when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));assertThrows(ResponseStatusException.class,()->workflow.transition(100L,student,"confirm-return"));assertEquals(BookingStatus.RETURN_PENDING_CONFIRMATION,b.status);}
 @Test void recordsIncidentResolutionAndAudit(){Booking b=makeBooking(BookingStatus.COMPLETED);Incident i=new Incident();i.id=200L;i.booking=b;i.status=IncidentStatus.OPEN;when(incidents.findByIdForUpdate(200L)).thenReturn(Optional.of(i));Incident resolved=workflow.resolve(200L,new ResolveIn("Inspected and documented"),owner);assertEquals(IncidentStatus.RESOLVED,resolved.status);assertEquals("Inspected and documented",resolved.resolutionNote);verify(audit).save(argThat(e->e.action.equals("INCIDENT_RESOLVED")));}
 @Test void createsIncidentAndAuditsIt(){Booking b=makeBooking(BookingStatus.CHECKED_OUT);when(bookings.findById(100L)).thenReturn(Optional.of(b));Incident result=workflow.incident(100L,new IncidentIn(IncidentType.DAMAGE,"Tripod latch is damaged"),student);assertEquals(IncidentStatus.OPEN,result.status);assertEquals(IncidentType.DAMAGE,result.type);verify(audit).save(argThat(e->e.action.equals("INCIDENT_REPORTED")&&e.entityId.equals(100L)));}
 @Test void promotesFirstEligibleWaitlistEntryAfterCancellation(){Booking cancelled=makeBooking(BookingStatus.APPROVED);Booking waiting=makeBooking(BookingStatus.WAITLISTED);waiting.id=101L;waiting.startTime=OffsetDateTime.now().plusDays(3);waiting.endTime=waiting.startTime.plusHours(2);when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(cancelled));when(bookings.findByResourceIdAndStatusOrderByCreatedAtAscIdAsc(30L,BookingStatus.WAITLISTED)).thenReturn(List.of(waiting));workflow.transition(100L,student,"cancel");assertEquals(BookingStatus.PENDING,waiting.status);assertTrue(waiting.decisionReason.contains("FIFO"));verify(audit).save(argThat(e->e.action.equals("WAITLIST_PROMOTED")&&e.entityId.equals(101L)));}
 @Test void refusesOtherUserBookingOperations(){Booking b=makeBooking(BookingStatus.PENDING);User stranger=new User("Stranger","stranger@example.edu",Role.USER);stranger.id=99L;when(bookings.findByIdForUpdate(100L)).thenReturn(Optional.of(b));assertThrows(ResponseStatusException.class,()->workflow.transition(100L,stranger,"cancel"));}
 Booking makeBooking(BookingStatus status){Booking b=new Booking();b.id=100L;b.resource=camera;b.requester=student;b.status=status;b.startTime=request().startTime();b.endTime=b.startTime.plusHours(2);b.purpose="test";return b;}
}
